	sections = {
		{
			title = "Summary",
			text = [=[The library is what remains of the Monastery's old learning. Its shelves hold works of history, lore and ritual gathered over long years, and some of them are rare beyond price: a mythology of the titans, a compendium of the fallen, a primer on the first days of the undead threat, a mage's book of rituals. The Crusade uses the books to train its paladins against the dead. It lets no one else read them. The houndmaster's trackers roam the outer cloisters, and the arcanist guards the inner hall.]=],
		},
	},
})

